package com.crm.notification.controller;
import com.crm.notification.entity.Notification; import com.crm.notification.repository.NotificationRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/notifications") public class NotificationController { private final NotificationRepository repo; public NotificationController(NotificationRepository repo){this.repo=repo;} @GetMapping("/user/{userId}") public List<Notification> byUser(@PathVariable Long userId){return repo.findByUserIdOrderByCreatedAtDesc(userId);} @PostMapping public ResponseEntity<Notification> create(@RequestBody Notification x){return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(x));} @PatchMapping("/{id}/read") public ResponseEntity<Notification> read(@PathVariable Long id){return repo.findById(id).map(e->{e.setReadFlag(true);return ResponseEntity.ok(repo.save(e));}).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();} }